('caburgua','parcela','publicada','Mirador del Villarrica – Parcela Premium | Caburgua','Exclusiva parcela de 5.000 m² ubicada en un condominio privado de Caburgua, uno de los destinos más exclusivos y valorados de la Región de La Araucanía. La propiedad ofrece una privilegiada vista al imponente volcán Villarrica y acceso al río dentro del condominio, combinando privacidad, seguridad y un entorno natural de categoría internacional. Además, el proyecto cuenta con aguas termales, convirtiéndose en un lugar ideal para disfrutar durante todo el año. Su ubicación permite acceder en pocos minutos al Lago Caburgua, famoso por sus aguas cristalinas y playas naturales, así como al Parque Nacional Huerquehue, reconocido por sus bosques nativos, senderos, lagunas de montaña y una de las mayores concentraciones de araucarias del país. También se encuentra muy cerca de Pucón, capital del turismo aventura en Chile, donde es posible practicar esquí, rafting, kayak, pesca deportiva, canopy, trekking y una amplia oferta gastronómica y hotelera. La propiedad cuenta con Rol Propio, disponibilidad de agua y energía eléctrica, ofreciendo una excelente oportunidad para construir una residencia de alto estándar, una segunda vivienda o desarrollar un proyecto turístico de lujo. Una inversión patrimonial única en uno de los sectores con mayor demanda y valorización del sur de Chile.','La Araucanía','Pucón',null,-39.25332,-71.79639,5000,200000000,'Propio','Disponible','Disponible','Por confirmar','Sí','Sí',true,'["naturaleza", "agua"]'::jsonb,'{"source_legacy_id": "caburgua", "origen": "parcelas.js", "imagen_principal": "image/cesar_Caburgua/cesar_caburgua_(5).webp", "imagenes": ["image/cesar_Caburgua/cesar_caburgua_(5).webp", "image/cesar_Caburgua/cesar_caburgua_(1).webp", "image/cesar_Caburgua/cesar_caburgua_ (2).webp", "image/cesar_Caburgua/cesar_caburgua_(3).webp", "image/cesar_Caburgua/cesar_caburgua_ (4).webp", "image/cesar_Caburgua/cesar_caburgua_(6).gif", "image/cesar_Caburgua/cesar_caburgua_(7).webp"], "detalle_legacy": "PARCELAS/LOS LAGOS/Caburgua.html", "facilidad_pago": "no", "naturaleza": "si", "servicios_cercanos": "si", "distancia_concepcion": null, "tiempo_concepcion": null}'::jsonb),
('campo_ruta_cabrero','campo','publicada','Ruta Concepción–Cabrero – Campo Estratégico 2 Hectáreas | Yumbel','Campo de 20.000 m² (2 hectáreas) ubicado en un estratégico sector de la ruta que conecta Concepción, Cabrero, Yumbel y Los Ángeles, una de las principales vías de comunicación del centro-sur de Chile. Su excelente ubicación y acceso lo convierten en una alternativa ideal para desarrollar un proyecto habitacional, turístico, agrícola o comercial, aprovechando el constante flujo vehicular de la zona. La propiedad se entrega con puntera de agua y cerco perimetral, facilitando el inicio de cualquier proyecto. Su amplia superficie permite construir una vivienda, bodegas, galpones, cabañas, un centro de eventos o un emprendimiento rural, manteniendo espacios suficientes para áreas verdes o producción agrícola. La comuna de Yumbel es reconocida por su tradición campesina, su creciente desarrollo inmobiliario y el histórico Santuario de San Sebastián, uno de los principales centros de peregrinación de Chile, que atrae cientos de miles de visitantes cada año. Además, la conectividad con Concepción, Cabrero y Los Ángeles fortalece el potencial de valorización de esta propiedad. Una excelente oportunidad para invertir en un campo con ubicación privilegiada, gran visibilidad y múltiples posibilidades de desarrollo.','Biobío','Yumbel',null,-36.9928,-72.59044,20000,95000000,'Por confirmar','Disponible','Por confirmar','Por confirmar','Por confirmar','Por confirmar',false,'[]'::jsonb,'{"source_legacy_id": "campo_ruta_cabrero", "origen": "parcelas.js", "imagen_principal": "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_2/ruta_concepcion_7000 (9).webp", "imagenes": ["image/claudio_ruiz/fotos/yumbel_ruta_concepcion_2/ruta_concepcion_7000 (9).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_2/ruta_concepcion_7000 (1).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_2/ruta_concepcion_7000 (5).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_2/ruta_concepcion_7000 (8).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_2/ruta_concepcion_7000 (10).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_1/ruta_6500_ (3).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_1/ruta_6500_ (1).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_1/ruta_6500_ (2).webp", "image/claudio_ruiz/fotos/yumbel_ruta_concepcion_1/ruta_plano_completo.webp"], "detalle_legacy": "campo_ruta_cabrero.html", "facilidad_pago": "si", "naturaleza": "no", "servicios_cercanos": "si", "distancia_concepcion": null, "tiempo_concepcion": null}'::jsonb)
on conflict(codigo) do update set
 tipo=excluded.tipo,
 titulo=coalesce(nullif(public.tpl_propiedades.titulo,''),excluded.titulo),
 descripcion=coalesce(nullif(public.tpl_propiedades.descripcion,''),excluded.descripcion),
 region=coalesce(nullif(public.tpl_propiedades.region,''),excluded.region),
 comuna=coalesce(nullif(public.tpl_propiedades.comuna,''),excluded.comuna),
 lat=coalesce(public.tpl_propiedades.lat,excluded.lat),lng=coalesce(public.tpl_propiedades.lng,excluded.lng),
 superficie_m2=coalesce(public.tpl_propiedades.superficie_m2,excluded.superficie_m2),
 precio_publicado=coalesce(public.tpl_propiedades.precio_publicado,excluded.precio_publicado),
 metadata=public.tpl_propiedades.metadata||excluded.metadata,
 updated_at=now();

update public.tpl_propiedades set publicada_at=coalesce(publicada_at,now()) where metadata->>'origen'='parcelas.js' and estado='publicada';

-- Registra las imágenes históricas sin duplicarlas.
create unique index if not exists tpl_propiedad_imagenes_legacy_unique on public.tpl_propiedad_imagenes(propiedad_id,(coalesce(url,storage_path))) where coalesce(url,storage_path) is not null;

