create or replace view public.crm_parcelas as
select
  p.*,
  case when p.superficie_m2>0 and p.precio_publicado>0 then round(p.precio_publicado::numeric/p.superficie_m2) end precio_publicado_m2,
  t.valor_tpl_m2,t.referencia_comunal_m2,t.clasificacion,t.es_oportunidad,
  coalesce(img.imagen_principal,p.metadata->>'imagen_principal') as imagen_principal,
  coalesce(img.imagenes,p.metadata->'imagenes','[]'::jsonb) as imagenes,
  coalesce(img.total_imagenes, jsonb_array_length(coalesce(p.metadata->'imagenes','[]'::jsonb))) as total_imagenes
from public.tpl_propiedades p
left join lateral (
 select x.valor_tpl_m2,x.referencia_comunal_m2,x.clasificacion,x.es_oportunidad
 from public.tpl_tasaciones x where x.propiedad_id=p.id order by x.created_at desc limit 1
) t on true
left join lateral (
 select
   (array_agg(coalesce(pi.url,pi.storage_path) order by pi.es_portada desc,pi.orden asc))[1] as imagen_principal,
   jsonb_agg(coalesce(pi.url,pi.storage_path) order by pi.es_portada desc,pi.orden asc) as imagenes,
   count(*)::int as total_imagenes
 from public.tpl_propiedad_imagenes pi where pi.propiedad_id=p.id
) img on true
where p.tipo in ('parcela','campo');

create or replace view public.crm_casas as
select c.*,cp.id oferta_principal_id,cp.partner_actor_id,cp.nombre_proveedor_pendiente,cp.tipo_relacion,cp.plazo_estimado_dias,
 cp.garantia,cp.vigencia_precio_hasta,ci.id catalogo_item_id,ci.estado estado_publicacion,
 coalesce(c.imagenes->>0,ci.imagen_principal_url) imagen_principal,
 coalesce(jsonb_array_length(c.imagenes),0) total_imagenes,
 coalesce(jsonb_array_length(c.planos),0) total_planos
from public.tpl_casas c
left join public.tpl_casa_proveedores cp on cp.casa_id=c.id and cp.es_oferta_principal and cp.estado<>'archivada'
left join public.tpl_catalogo_items ci on ci.casa_id=c.id and ci.tipo='casa' and ci.estado<>'archivado';

-- Reemplaza el snapshot para asegurar que las vistas nuevas se reflejen inmediatamente.
create or replace function public.tpl_crm_snapshot_v1()
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_result jsonb;begin
 if auth.uid() is null or not public.tpl_es_staff() then raise exception 'Acceso CRM no autorizado' using errcode='42501'; end if;
 select jsonb_build_object(
  'generated_at',now(),
  'compradores',coalesce((select jsonb_agg(to_jsonb(x) order by x.nombre nulls last) from public.crm_compradores x),'[]'::jsonb),
  'duenos',coalesce((select jsonb_agg(to_jsonb(x) order by x.nombre nulls last) from public.crm_duenos x),'[]'::jsonb),
  'parcelas',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from public.crm_parcelas x),'[]'::jsonb),
  'parcelas_casas',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from public.crm_parcelas_casas x),'[]'::jsonb),
  'casas',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from public.crm_casas x),'[]'::jsonb),
  'operaciones',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from public.crm_operaciones_activas x),'[]'::jsonb),
  'revision',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from public.crm_operaciones_revision x),'[]'::jsonb),
  'tareas',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from public.tpl_tareas x where x.estado in ('pendiente','en_progreso','esperando') limit 300),'[]'::jsonb),
  'alertas',coalesce((select jsonb_agg(to_jsonb(x) order by x.fecha_relevante desc) from public.crm_alertas x),'[]'::jsonb),
  'publicaciones_revision',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from public.tpl_publicaciones x where x.estado in ('enviada','pendiente_revision','requiere_correccion')),'[]'::jsonb),
  'partners',coalesce((select jsonb_agg(to_jsonb(x) order by x.nombre) from public.crm_partners x),'[]'::jsonb),
  'tasaciones',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from public.tpl_tasaciones x limit 300),'[]'::jsonb),
  'analytics_diario',coalesce((select jsonb_agg(to_jsonb(x) order by x.dia desc) from public.crm_analytics_diario x limit 300),'[]'::jsonb),
  'eventos',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from public.tpl_eventos x limit 300),'[]'::jsonb),
  'mensajes_pendientes',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from public.tpl_mensajes_salida x where x.estado in ('pendiente','error') limit 300),'[]'::jsonb)
 ) into v_result;
 return v_result;
end $$;
revoke all on function public.tpl_crm_snapshot_v1() from public;
grant execute on function public.tpl_crm_snapshot_v1() to authenticated;

commit;
